INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000065',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe a full work day in detail in Kannada","Use office vocabulary and time expressions","Talk about meetings, tasks, and colleagues"],"explanation":{"intro":"Describing your work day in detail builds on A1 work vocabulary with more nuanced expressions for meetings, tasks, deadlines, and workplace interactions.","culturalNote":"Work culture in Bengaluru IT: Bengaluru is the IT capital of India. The typical IT professional day: beLigge 9 ge office ge baa (come to office by 9am), standup meeting (daily standup — 15-minute team sync), tasks assign aagutte (tasks get assigned), lunch break (typically 1-2pm), review meeting (code review or project review), evening 6-7 ge mane hogi (go home 6-7 evening). Work-life balance: a hot topic — ''late sitting'' (staying late) is common but increasingly criticized. WFH (work from home): post-COVID, very common in Bengaluru IT — ''aaj WFH ide'' (today I have WFH) is a common statement. Office food: many IT parks have large cafeterias — biryani Fridays is a tradition in several companies! Deadline pressure: ''sprint end aagutte'' (the sprint is ending) — Agile terminology mixed with Kannada is very natural in Bengaluru workplaces. Colleagues: ''teammate'' (English), ''manager'' (English), ''senior'' (English) are all used directly."},"examples":[{"sentence":"Ivaththu nanna kaela thumba busy itu — beLigge standup, nantara review meeting, kaDeyalli deployment maadide.","english":"Today my work was very busy — morning standup, then review meeting, finally I did the deployment."},{"sentence":"Nanna manager naakke naale deadline nodiri anta heLidaare — naanu stress aagtiddeeni.","english":"My manager told me to see the deadline tomorrow — I am getting stressed."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe my work day in detail including meetings, tasks, and colleagues."}}',
'{"items":[{"word":"standup","translation":"standup meeting (daily team sync)","transliteration":"standup","pronunciation":"STAND-up","example":"beLigge standup ide"},{"word":"deadline","translation":"deadline (project deadline)","transliteration":"deadline","pronunciation":"DED-line","example":"naale deadline"},{"word":"deployment","translation":"deployment (software release)","transliteration":"deployment","pronunciation":"de-PLOI-ment","example":"deployment maadide"},{"word":"sprint","translation":"sprint (Agile work cycle)","transliteration":"sprint","pronunciation":"sprint","example":"sprint end aagutte"},{"word":"busy","translation":"busy (very common — English used directly)","transliteration":"busy","pronunciation":"BI-zi","example":"thumba busy"},{"word":"stress","translation":"stress (English word — very common in IT context)","transliteration":"stress","pronunciation":"stres","example":"stress aagtiddeeni"}]}',
'{"title":"Office Kannada — describing work day","pattern":"Beligge X maadide, nantara Y, kaDeyalli Z poorthi maadide = In the morning I did X, then Y, finally completed Z. Meeting ide = there is a meeting. X poorthi aayitu = X is completed. Naakke Y maadabeku = I have to do Y (task assigned to me). Nanna manager X heLidaare = my manager said X.","explanation":"Work day vocabulary: standup (daily meeting), meeting (any meeting), task (task — English), deadline (deadline), sprint (Agile sprint), deployment (deployment), review (code/project review). Time structure: beLigge (morning), madyaahna (afternoon/lunch), saayankala (evening), raatruu (night). Progress: X maaduttiddeeni (I am doing X — ongoing), X maadide (I did X — completed), X baaki ide (X is remaining — yet to do). Problem: X block aagide (X is blocked), help beku (I need help). Done: poorthi maadide (I completed it), close maadide (I closed it — issue/ticket). Tomorrow plan: naale X maaduttini (tomorrow I will do X).","examples":[{"sentence":"Ivaththu nanna sprint tasks ellaa poorthi maadide — naale navin feature shuru maaduttini.","english":"Today I completed all my sprint tasks — tomorrow I will start a new feature."},{"sentence":"Meeting alli naanu nanna progress share maadide — manager thumba khushi aadaare.","english":"In the meeting I shared my progress — the manager was very happy."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"deployment means in an IT work context?","options":["software release to production","daily meeting","task assignment","code review"],"correctAnswer":"software release to production"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today my work was very busy — morning standup, then review meeting, finally I did the deployment.","options":["Ivaththu nanna kaela thumba busy itu — beLigge standup, nantara review meeting, kaDeyalli deployment maadide.","Naale nanna kaela thumba busy itu — beLigge standup, nantara review meeting, kaDeyalli deployment maadide.","Ivaththu nanna kaela thakku busy itu — beLigge standup, nantara review meeting, kaDeyalli deployment maadide.","Ivaththu nanna kaela thumba busy itu — saayankala standup, nantara review meeting, kaDeyalli deployment maadide."],"correctAnswer":"Ivaththu nanna kaela thumba busy itu — beLigge standup, nantara review meeting, kaDeyalli deployment maadide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ivaththu nanna sprint tasks ellaa ___ maadide — naale navin feature shuru maaduttini.","options":["poorthi","cancel","postpone","block"],"correctAnswer":"poorthi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Today I completed all my sprint tasks — tomorrow I will start a new feature.","wordBankItems":["Ivaththu","nanna","sprint","tasks","ellaa","poorthi","maadide","—","naale","navin","feature","shuru","maaduttini","."],"correctAnswer":"Ivaththu nanna sprint tasks ellaa poorthi maadide — naale navin feature shuru maaduttini ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"X baaki ide means?","options":["X is remaining / yet to do","X is done","X is blocked","X is started"],"correctAnswer":"X is remaining / yet to do"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000066',1,'APPROVED','PUBLISHED',
'{"objectives":["Handle disagreements politely in Kannada","Use aadare, naanu bhinnaabipraayaadalli for polite disagreement","Maintain respectful tone while expressing opposing views"],"explanation":{"intro":"Disagreement vocabulary covers how to politely contradict someone, express a different view, or respectfully push back — essential for workplace and social interactions.","culturalNote":"Disagreement in Karnataka culture: direct confrontation is generally avoided in traditional Karnataka culture — people prefer indirect disagreement. The phrase ''sari ide'' (okay/fine) is often used as a non-committal response even when one disagrees — silence and ''sari'' do not always mean agreement! Workplace disagreement: in IT companies, disagreement in meetings is more normalized — ''naanu bhinnaabipraayaadalli'' (I have a different opinion) is acceptable. Family disagreement: disagreeing with elders is done very carefully and indirectly — ''aadare ajja, ondu vishaya keLuttini'' (but grandfather, may I ask one thing?). Political disagreement: Kannadigas are passionate about politics — disagreements can be lively! Language politics: any suggestion that Karnataka should use Hindi over Kannada provokes strong disagreement — ''naanu idakke sahmatagalla'' (I do not agree to this). Religious harmony: Karnataka has generally maintained communal harmony — interfaith disputes handled with patience."},"examples":[{"sentence":"Naanu nimage agree aguttini, aadare ee vishaya alli naanu bhinnaabipraayaadalli iddini.","english":"I agree with you (generally), but on this matter I have a different opinion."},{"sentence":"Neevu heLidaddu sari ide, aadare ondu vishaya add maadabeku anta nambuttini.","english":"What you said is right, but I believe one thing needs to be added."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can politely disagree and express different opinions in Kannada."}}',
'{"items":[{"word":"bhinnaabipraaya","translation":"different opinion/different view","transliteration":"bhinnaabipraaya","pronunciation":"bhin-naa-bi-PRAA-ya","example":"naanna bhinnaabipraaya"},{"word":"sahmatagalla","translation":"I do not agree (strong disagreement)","transliteration":"sahmatagalla","pronunciation":"sah-MA-ta-GAL-la","example":"naanu idakke sahmatagalla"},{"word":"ondu vishaya","translation":"one thing/one matter (for adding a point)","transliteration":"ondu vishaya","pronunciation":"ON-du VI-sha-ya","example":"ondu vishaya keLuttini"},{"word":"naanna abipraayalli","translation":"in my opinion (literally: in my view)","transliteration":"naanna abipraayalli","pronunciation":"NAAN-na a-bi-PRAA-ya-lli","example":"naanna abipraayalli"},{"word":"nimma heLike sarigide aadare","translation":"what you said is right but...","transliteration":"nimma heLike sarigide aadare","pronunciation":"NIM-ma he-LI-ke SA-ri-gi-de AA-da-re","example":"nimma heLike sarigide aadare..."},{"word":"hecchaagi yochisi","translation":"think more carefully (suggesting reconsideration)","transliteration":"hecchaagi yochisi","pronunciation":"hec-CHAA-gi YO-chi-si","example":"hecchaagi yochisi nodiri"}]}',
'{"title":"Polite disagreement in Kannada — bhinnaabipraaya","pattern":"Naanu agree aguttini, aadare... = I agree, but... Naanna abipraayalli X = In my opinion X. Nimma heLike sarigide, aadare... = What you said is right, but... Naanu idakke sahmatagalla = I do not agree to this (firm). Ondu vishaya add maadabeku = one thing needs to be added (softening disagreement by offering addition rather than contradiction).","explanation":"Polite disagreement patterns in Kannada: (1) Partial agreement then redirect: agree aguttini, aadare (I agree, but). (2) Adding perspective: naanna abipraayalli (in my opinion — softens). (3) Questioning gently: eeke anta nambuttiri? (why do you believe that?). (4) Suggesting reconsideration: hecchaagi yochisi (think more carefully — polite). (5) Strong disagreement: naanu idakke sahmatagalla (I do not agree to this). (6) Disagreement with respect for elder: nimma abipraayakke gouri iDuttini, aadare... (I respect your opinion, but... — gouri iDuttini = I give respect/value). Cultural tip: end disagreements with ''naanu nimage sahaaya maaduttini'' (I will help you) or ''namma iddaru seri maaduvona'' (let us two work it out together) to maintain harmony.","examples":[{"sentence":"Naanna abipraayalli ee project alli munna testing beku, aadare nimma nirnaya naakke artha aagutte.","english":"In my opinion this project needs testing first, but I understand your decision."},{"sentence":"Naanu idakke poorthi sahmatagalla — hecchaagi yochisi nodiri, dayavittu.","english":"I do not completely agree to this — please think more carefully about it."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"bhinnaabipraaya means?","options":["different opinion/different view","agreement","argument","decision"],"correctAnswer":"different opinion/different view"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I agree with you (generally), but on this matter I have a different opinion.","options":["Naanu nimage agree aguttini, aadare ee vishaya alli naanu bhinnaabipraayaadalli iddini.","Naanu nimage agree aguttini, aadare ee vishaya alli naanu sahmatagalla.","Naanu nimage disagree maaduttini, aadare ee vishaya alli naanu bhinnaabipraayaadalli iddini.","Avanu nimage agree aguttaane, aadare ee vishaya alli naanu bhinnaabipraayaadalli iddini."],"correctAnswer":"Naanu nimage agree aguttini, aadare ee vishaya alli naanu bhinnaabipraayaadalli iddini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanna ___ ee project alli munna testing beku, aadare nimma nirnaya naakke artha aagutte.","options":["abipraayalli","vishayalli","bhinnaabipraayalli","heLikeyalli"],"correctAnswer":"abipraayalli"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I do not completely agree to this — please think more carefully about it.","wordBankItems":["Naanu","idakke","poorthi","sahmatagalla","—","hecchaagi","yochisi","nodiri",",","dayavittu","."],"correctAnswer":"Naanu idakke poorthi sahmatagalla — hecchaagi yochisi nodiri , dayavittu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"sahmatagalla means?","options":["I do not agree","I agree","I understand","I accept"],"correctAnswer":"I do not agree"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000067',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe weekend activities in Kannada","Use viikenda and saavakaasha vocabulary","Talk about hobbies, outings, and relaxation"],"explanation":{"intro":"Weekend activities vocabulary covers how to describe what you did on the weekend — from family outings to solo hobbies to social events.","culturalNote":"Weekends in Karnataka: weekend culture in Bengaluru is very active. Common weekend activities: (1) Temple visits — Nandi Hills drive (early morning, 60km from Bengaluru — famous sunrise view), Tirupati trip (weekend pilgrimage), Dharmasthala (pilgimage town in Dakshina Kannada). (2) Nature/adventure: Coorg (Kodagu) trip — coffee estates, waterfalls, Brahmagiri trek. Chikmagalur — coffee country, Mullayanagiri peak (Karnataka''s highest). (3) Bengaluru outings: Cubbon Park walk, Lalbagh Botanical Garden, Namma Metro ride to new areas. (4) Food outings: MTR for breakfast, Sri Sagar for idli, kosambari, masala dosa crawl on VV Puram food street. (5) Movies: Kannada film (talkies) — Sandalwood movie on first weekend (payday weekend rush!). (6) Family time: namma ooru (native village) visit — many Bengaluru IT workers visit their native town on long weekends. (7) Sports: cricket in apartment complex, badminton courts — very popular."},"examples":[{"sentence":"Ee viikenda naanu nanna family jote Nandi Hills ge hode — sunrise channa itu, coffee kudidivi.","english":"This weekend I went to Nandi Hills with my family — the sunrise was beautiful, we drank coffee."},{"sentence":"Saavakaashada dina naanu mane alli rest maadide haagu Kannada novels odide.","english":"On the holiday I rested at home and read Kannada novels."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe weekend activities and outings in Kannada."}}',
'{"items":[{"word":"viikenda","translation":"weekend","transliteration":"viikenda","pronunciation":"VEE-ken-da","example":"ee viikenda"},{"word":"saavakaasha","translation":"holiday/day off","transliteration":"saavakaasha","pronunciation":"saa-va-KAA-sha","example":"saavakaashada dina"},{"word":"outing","translation":"outing/day trip","transliteration":"outing","pronunciation":"AW-ting","example":"family outing"},{"word":"trek","translation":"trek/hike","transliteration":"trek","pronunciation":"trek","example":"betta trek"},{"word":"sunrise","translation":"sunrise","transliteration":"sunrise","pronunciation":"SAN-raiz","example":"sunrise nodide"},{"word":"rest maadide","translation":"I rested / I took rest","transliteration":"rest maadide","pronunciation":"rest MAA-di-de","example":"mane alli rest maadide"}]}',
'{"title":"Viikenda — weekend activity vocabulary in Kannada","pattern":"Ee viikenda X ge hode = This weekend I went to X. X jote Y maadide = I did Y with X (jote = with). Saavakaashada dina = on the holiday. Viikenda plan: naale viikenda X maadabeku anta yochane ide (plan to do X this weekend). Reporting back: viikenda hege itu? — Channa itu! X ge hode (How was the weekend? — It was great! I went to X).","explanation":"Weekend vocabulary in Kannada: viikenda (weekend — English adopted), saavakaasha (holiday — Kannada), saavakaashada dina (holiday day — formal). Outing vocabulary: picnic (picnic), trip (trip), outing (outing — all English used directly). Nature words: betta (hill/mountain), naadi (river), kaadu (forest), falls (waterfall — English + Kannada: jalapaata). Activities: odide (I read), nodide (I watched/saw), aaDide (I played), kudidivi (we drank). With whom: nanna family jote (with my family), nanna geleja jote (with my friends), ondu (alone). How was it: channagitu (it was nice), adbhutavaagitu (it was wonderful), thumba enjoy maadide (I enjoyed a lot). Next plans: munde X ge hogabeku anta ide (planning to go to X next time).","examples":[{"sentence":"Naanu nanna mitragaLa jote Chikmagalur ge hode — coffee estate nodide, thumba channa itu.","english":"I went to Chikmagalur with my friends — I saw the coffee estate, it was very beautiful."},{"sentence":"Viikenda plan: Coorg ge hogi, trek maadi, oota tindu baa — super plan alla vaa?","english":"Weekend plan: go to Coorg, do trek, eat food and come back — isn''t it a super plan?"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"saavakaasha means?","options":["holiday/day off","weekend","outing","rest"],"correctAnswer":"holiday/day off"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"This weekend I went to Nandi Hills with my family — the sunrise was beautiful, we drank coffee.","options":["Ee viikenda naanu nanna family jote Nandi Hills ge hode — sunrise channa itu, coffee kudidivi.","Ee viikenda naanu nanna family jote Coorg ge hode — sunrise channa itu, coffee kudidivi.","Ee viikenda naanu nanna geleja jote Nandi Hills ge hode — sunrise channa itu, coffee kudidivi.","Ee viikenda naanu nanna family jote Nandi Hills ge hoguttini — sunrise channa itu, coffee kudidivi."],"correctAnswer":"Ee viikenda naanu nanna family jote Nandi Hills ge hode — sunrise channa itu, coffee kudidivi."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu nanna mitragaLa jote Chikmagalur ge hode — coffee estate ___,  thumba channa itu.","options":["nodide","maadide","kudidivi","odide"],"correctAnswer":"nodide"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I went to Chikmagalur with my friends — I saw the coffee estate, it was very beautiful.","wordBankItems":["Naanu","nanna","mitragaLa","jote","Chikmagalur","ge","hode","—","coffee","estate","nodide",",","thumba","channa","itu","."],"correctAnswer":"Naanu nanna mitragaLa jote Chikmagalur ge hode — coffee estate nodide , thumba channa itu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"thumba enjoy maadide means?","options":["I enjoyed a lot","I rested a lot","I ate a lot","I travelled a lot"],"correctAnswer":"I enjoyed a lot"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000068',1,'APPROVED','PUBLISHED',
'{"objectives":["Talk about health and lifestyle in Kannada","Describe healthy habits and routines","Discuss diet, exercise, and wellness in Kannada"],"explanation":{"intro":"Health and lifestyle vocabulary builds on basic health words to cover broader wellness topics — diet, exercise, sleep, mental health, and healthy habits.","culturalNote":"Health culture in Karnataka: (1) Yoga: Karnataka has a deep yoga tradition — Mysuru (Mysore) is the world capital of Ashtanga Yoga — K. Pattabhi Jois founded Ashtanga Yoga in Mysuru. Many Bengaluru professionals practice yoga. (2) Diet: South Indian diet is considered healthy — rice, lentils (bele), vegetables (tarkari), buttermilk (majjige) — nutritionally balanced. Ayurveda: Karnataka has a strong Ayurveda tradition — Dharwad and Bengaluru have Ayurvedic hospitals. (3) Sleep: IT culture and ''late sitting'' has created a sleep health crisis in Bengaluru. (4) Mental health: increasing awareness in urban Karnataka — ''naakke mental peace beku'' (I need mental peace) is a common statement. (5) Walking: Bengaluru''s parks (Cubbon Park, Lalbagh) are packed with morning walkers. Walking groups (walking group) are popular. (6) Traditional health: a cup of turmeric milk (arishina halu) for colds — a Karnataka household remedy. Neem (bevu) paste for skin. (7) Annual checkup: corporate health checkup (yearly health checkup) is standard for IT employees."},"examples":[{"sentence":"Nanna lifestyle improve maaDabekanta beLigge yoga maaDuttiddeeni haagu raatruu bega malagutte iddini.","english":"Wanting to improve my lifestyle I am doing yoga in the morning and sleeping early at night."},{"sentence":"Doctor naakke heLidaare ki tarashari tarkari tinnu haagu water hecchaagi kudi anta.","english":"The doctor told me to eat green vegetables regularly and drink more water."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss health, lifestyle, and wellness in Kannada."}}',
'{"items":[{"word":"lifestyle","translation":"lifestyle (English word used directly)","transliteration":"lifestyle","pronunciation":"LIFE-stail","example":"healthy lifestyle"},{"word":"yoga","translation":"yoga","transliteration":"yoga","pronunciation":"YO-ga","example":"beLigge yoga"},{"word":"tarashari","translation":"regularly/consistently","transliteration":"tarashari","pronunciation":"ta-ra-SHA-ri","example":"tarashari maaDabeku"},{"word":"tarkari","translation":"vegetables (cooked — also: curry vegetables)","transliteration":"tarkari","pronunciation":"tar-KA-ri","example":"hasi tarkari"},{"word":"majjige","translation":"buttermilk (healthy South Indian drink)","transliteration":"majjige","pronunciation":"MAJ-ji-ge","example":"oota nantara majjige"},{"word":"mental peace","translation":"mental peace/inner calm","transliteration":"mental peace","pronunciation":"MEN-tal PEES","example":"naakke mental peace beku"}]}',
'{"title":"Health and wellness vocabulary in Kannada","pattern":"Beligge X maaDuttiddeeni = I am doing X in the morning (healthy habit). Tarashari X tinnu = eat X regularly. X improve maaDabeku anta = wanting to improve X. Doctor heLidaare ki X = doctor told me to X. Health routine: beLigge yoga (morning yoga) + saayankala naDeyu (evening walk) + raatruu bega malagoodu (sleep early at night).","explanation":"Health vocabulary in Kannada: arogya (health — general), dEhaarogya (physical health), maanasika arogya (mental health). Common health habits: yoga maaDuvudu (doing yoga), naDeyu (walking), ooduvudu (running), vyaayaama (exercise — general). Diet: tarashari tarkari tinnu (eat vegetables regularly), neeru hecchaagi kuDu (drink more water), fast food kammi maaDu (reduce fast food). Doctor advice: doctor heLidaare ki X maaDabeku (doctor said to do X). Illness: swalpa healthy agilla (not feeling well — casual). Checkup: yearly checkup maaDidu (had annual checkup). Wellness: samadhaanapaTTiddini (I feel content/at peace — strong wellness word from samadhaana = contentment).","examples":[{"sentence":"Ee tiNgaLinda naaNavarDa naDeyu shuru maadide — beLigge 6 ge Lalbagh ge hoguttiddeeni.","english":"From this month I have started a walking routine — I am going to Lalbagh at 6 in the morning."},{"sentence":"Healthy aagalikante arishina halu kudi haagu screen time kammi maaDu anta amma heLtaLe.","english":"To be healthy, drink turmeric milk and reduce screen time, says mother."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"tarashari means?","options":["regularly/consistently","sometimes","rarely","always"],"correctAnswer":"regularly/consistently"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Wanting to improve my lifestyle I am doing yoga in the morning and sleeping early at night.","options":["Nanna lifestyle improve maaDabekanta beLigge yoga maaDuttiddeeni haagu raatruu bega malagutte iddini.","Nanna lifestyle improve maaDabekanta saayankala yoga maaDuttiddeeni haagu raatruu bega malagutte iddini.","Nanna lifestyle improve maaDabekanta beLigge yoga maaDuttiddeeni haagu beLigge bega malagutte iddini.","Nanna health improve maaDabekanta beLigge yoga maaDuttiddeeni haagu raatruu bega malagutte iddini."],"correctAnswer":"Nanna lifestyle improve maaDabekanta beLigge yoga maaDuttiddeeni haagu raatruu bega malagutte iddini."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Doctor naakke heLidaare ki tarashari tarkari tinnu haagu water ___ kudi anta.","options":["hecchaagi","kammi","bega","tarashari"],"correctAnswer":"hecchaagi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: From this month I have started a walking routine — I am going to Lalbagh at 6 in the morning.","wordBankItems":["Ee","tiNgaLinda","naaNavarDa","naDeyu","shuru","maadide","—","beLigge","6","ge","Lalbagh","ge","hoguttiddeeni","."],"correctAnswer":"Ee tiNgaLinda naaNavarDa naDeyu shuru maadide — beLigge 6 ge Lalbagh ge hoguttiddeeni ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"majjige means?","options":["buttermilk (healthy South Indian drink)","milk","curd","tea"],"correctAnswer":"buttermilk (healthy South Indian drink)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-000000000069',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss Karnataka''s major festivals in Kannada","Name and describe Dasara, Ugaadi, Kannada Rajyotsava","Express how festivals are celebrated"],"explanation":{"intro":"Karnataka festivals vocabulary covers the major celebrations of the state — their meaning, customs, special foods, and how to talk about them in Kannada.","culturalNote":"Karnataka''s major festivals: (1) Dasara (Navaratri Dasara): Karnataka''s biggest festival — 10 days in October. Mysuru Dasara is world-famous — Mysore Palace is lit with 100,000 lights, Jamboo Savari (elephant procession) on Vijayadashami. State holiday — official state festival (rajyotsava habba). Goddess Chamundeshwari (Chamundi) is worshipped. (2) Ugaadi: Kannada/Telugu New Year — usually March/April. New year is called ''Yugaadi'' in Kannada. Bevu-bella (neem + jaggery mixture) is eaten — symbolizing life''s mix of bitter and sweet. Panchangam (almanac) reading. New clothes (hosa baTTe). (3) Kannada Rajyotsava: November 1 — Karnataka statehood day (formation of Karnataka state in 1956). Red-yellow (kempu-hasiru) flag everywhere. Kannada songs, cultural programs, Rajyotsava award ceremony. (4) Sankranti: Harvest festival in January. Ellu-bella (sesame + jaggery) shared. Kite flying. (5) Ugadi/Deepavali/Holi: also celebrated widely. Deepavali is called Dipotsava in Kannada."},"examples":[{"sentence":"Dasara Karnataka''s rajyotsava habba — Mysuru alli 10 dina celebration aagutte, Jamboo Savari thumba prasiddha.","english":"Dasara is Karnataka''s state festival — in Mysuru celebration happens for 10 days, the Jamboo Savari is very famous."},{"sentence":"Ugaadi alli bevu-bella tinuttivi — jiivanalli kaara haagu sihi eraDuu ide anta meaning.","english":"At Ugaadi we eat bevu-bella — the meaning is that in life both bitter and sweet exist."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss Karnataka''s festivals and explain their significance in Kannada."}}',
'{"items":[{"word":"habba","translation":"festival/celebration","transliteration":"habba","pronunciation":"HAB-ba","example":"Dasara habba"},{"word":"Dasara","translation":"Dasara (Karnataka''s biggest festival — Navaratri/Vijayadashami)","transliteration":"Dasara","pronunciation":"DA-sa-ra","example":"Mysuru Dasara"},{"word":"Ugaadi","translation":"Ugaadi (Kannada New Year — March/April)","transliteration":"Ugaadi","pronunciation":"u-GAA-di","example":"Ugaadi habba"},{"word":"Rajyotsava","translation":"Karnataka Rajyotsava (November 1 — statehood day)","transliteration":"Rajyotsava","pronunciation":"raaj-YOT-sa-va","example":"Kannada Rajyotsava"},{"word":"bevu-bella","translation":"bevu-bella (neem+jaggery — Ugaadi ritual food)","transliteration":"bevu-bella","pronunciation":"BE-vu BEL-la","example":"Ugaadi alli bevu-bella"},{"word":"Jamboo Savari","translation":"Jamboo Savari (Dasara elephant procession in Mysuru)","transliteration":"Jamboo Savari","pronunciation":"JAM-boo sa-VA-ri","example":"Mysuru Jamboo Savari"}]}',
'{"title":"Karnataka festivals vocabulary","pattern":"X habba = X festival. X alli Y aagutte = Y happens at X (festival event). X tinuttivi = we eat X (festival food). Habba greeting: X shubhashayagalu = Happy X (festival wishes). Meaning: X anta meaning = the meaning is X.","explanation":"Festival vocabulary in Kannada: habba (festival), habbada dina (festival day), shubhashayagalu (best wishes — festival greeting). Festival verbs: celebrate maaDuvudu (to celebrate), puja maaDuvudu (to do puja/worship), prayer maaDuvudu (to pray), oota maaDisuvudu (to prepare feast). Festival foods: bevu-bella (Ugaadi), ellu-bella (Sankranti), payasa (kheer — Dasara/weddings), holige/obbattu (sweet stuffed roti — Ugaadi/Dasara). Festival clothing: hosa baTTe (new clothes), sari (saree), dhoti (men''s traditional wear). Decoration: rangoli/muggu (floor decoration), diipa (lamp/diya), torana (door decoration with mango leaves). Greeting relatives: habba alli akka/amma/ajja manege hoguvudu (visiting sister/mother/grandfather on festival day).","examples":[{"sentence":"Kannada Rajyotsava November 1 hakke bagutte — aa dinada kempu-hasiru flag noduvudu naakke thumba khushi koDutte.","english":"Kannada Rajyotsava comes on November 1 — seeing the red-yellow flag on that day gives me a lot of joy."},{"sentence":"Sankranti alli namma ooru alli ellu-bella henchuttivi haagu patanga haaruvudu ishtavaagutte.","english":"At Sankranti in our village we distribute ellu-bella and I like flying kites."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"habba means?","options":["festival/celebration","holiday","ritual","procession"],"correctAnswer":"festival/celebration"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"At Ugaadi we eat bevu-bella — the meaning is that in life both bitter and sweet exist.","options":["Ugaadi alli bevu-bella tinuttivi — jiivanalli kaara haagu sihi eraDuu ide anta meaning.","Dasara alli bevu-bella tinuttivi — jiivanalli kaara haagu sihi eraDuu ide anta meaning.","Ugaadi alli ellu-bella tinuttivi — jiivanalli kaara haagu sihi eraDuu ide anta meaning.","Ugaadi alli bevu-bella tinuttivi — jiivanalli kaara haagu sihi onDu ide anta meaning."],"correctAnswer":"Ugaadi alli bevu-bella tinuttivi — jiivanalli kaara haagu sihi eraDuu ide anta meaning."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Kannada Rajyotsava November 1 hakke bagutte — aa dinada kempu-hasiru flag noduvudu naakke thumba ___ koDutte.","options":["khushi","novu","stress","santosha"],"correctAnswer":"khushi"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Dasara is Karnataka''s state festival — in Mysuru celebration happens for 10 days, the Jamboo Savari is very famous.","wordBankItems":["Dasara","Karnataka''s","rajyotsava","habba","—","Mysuru","alli","10","dina","celebration","aagutte",",","Jamboo","Savari","thumba","prasiddha","."],"correctAnswer":"Dasara Karnataka''s rajyotsava habba — Mysuru alli 10 dina celebration aagutte , Jamboo Savari thumba prasiddha ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"Jamboo Savari is?","options":["Dasara elephant procession in Mysuru","a type of food","a folk dance","a religious ceremony"],"correctAnswer":"Dasara elephant procession in Mysuru"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss news and current affairs in Kannada","Use samachar vocabulary for events and opinions","Express views on current events"],"explanation":{"intro":"Discussing news and current affairs covers the vocabulary to follow and comment on news — from local Bengaluru events to national and global stories.","culturalNote":"News media in Karnataka: major Kannada newspapers: Vijaya Karnataka (largest circulation Kannada daily), Prajavani (oldest — since 1948 — progressive), Deccan Herald (English, Bengaluru-based), Udayavani (Mangaluru-based, Tulu coast focus). TV news: Tv9 Kannada, Suvarna News, Star Suvarna — major Kannada news channels. Digital: Kannada Prabha online, various YouTube news channels. News culture: Kannadigas are highly politically engaged. State politics (rajyakarana) is a passionate topic. Local Bengaluru news: BBMP (municipal corporation) news, Metro extension updates, IT park developments — very common topics. Sports news: RCB (Royal Challengers Bangalore) IPL news is obsessively followed. Film news: Sandalwood (Kannada film industry) news is widely consumed — film releases, box office. Language news: any news about Kannada language status, classical language status, or Hindi imposition gets major attention. Cricket: India vs Pakistan matches stop office work in Bengaluru!"},"examples":[{"sentence":"Ivaththu paper nodide ki Bengaluru Metro navin route extend aagutte anta — thumba oLLeya samachar.","english":"Today I saw in the paper that Bengaluru Metro will extend a new route — very good news."},{"sentence":"Rajyakarana vishaya alli naakke thumba asakti ide — ivaththu election results noduttiddeeni.","english":"I have a lot of interest in political matters — today I am watching election results."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can discuss news and current affairs in Kannada."}}',
'{"items":[{"word":"samachar","translation":"news (from Sanskrit/Hindi — widely used)","transliteration":"samachar","pronunciation":"sa-MA-char","example":"ivaththu samachar"},{"word":"paper","translation":"newspaper (English — very common)","transliteration":"paper","pronunciation":"PAY-per","example":"paper odide"},{"word":"rajyakarana","translation":"politics (literally: state management)","transliteration":"rajyakarana","pronunciation":"raaj-ya-KA-ra-na","example":"rajyakarana vishaya"},{"word":"asakti","translation":"interest/fascination","transliteration":"asakti","pronunciation":"aa-SAK-ti","example":"thumba asakti ide"},{"word":"election results","translation":"election results (English — commonly used)","transliteration":"election results","pronunciation":"i-LEK-shen RI-zults","example":"election results noduttiddeeni"},{"word":"extend","translation":"extend/expand (English — infrastructure context)","transliteration":"extend","pronunciation":"eks-TEND","example":"Metro route extend"}]}',
'{"title":"Samachar — discussing news and current events","pattern":"Paper alli heLide ki X = it said in the paper that X. X samachar thumba muhtvada = X news is very important. Naakke X vishaya alli asakti ide = I have interest in X topic. X aagutte anta keLidini = I heard that X will happen. Express opinion on news: ee samachar nambaagsuttilla (I can''t believe this news — surprise/shock), ee X nimage enu anisuttade? (what do you think about this X?).","explanation":"News vocabulary in Kannada: samachar (news), varthe (news item — more formal), paper (newspaper — English), news channel (English), digital samachar (online news). Current events vocabulary: election (election), government (sarkaara), budget (budget), infrastructure (infrastructure), Metro (Bengaluru Metro), startup (startup ecosystem), IT (IT sector). Opinions on news: X aagutte anta nambuttini (I believe X will happen), X aagabekalla anta nambuttini (I hope X doesn''t happen), X muhtvada vishaya (X is an important matter). Following news: tarashari paper oduttini (I read the paper regularly), TV news noduttiddeeni (I am watching TV news), online news check maaDuttini (I check online news). Breaking news: hosa samachar (new/fresh news), breaking news (English — used directly).","examples":[{"sentence":"Ivaththu samachar alli heLidaare ki Karnataka sarkaara navin scheme announce maadide — farmers ge direct benefit.","english":"Today in the news they said that Karnataka government announced a new scheme — direct benefit to farmers."},{"sentence":"RCB ee IPL final ge hogide anta samachar keLide — Bengaluru alli thumba excitement ide!","english":"I heard the news that RCB went to this IPL final — there is a lot of excitement in Bengaluru!"}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"rajyakarana means?","options":["politics (literally: state management)","government","election","news"],"correctAnswer":"politics (literally: state management)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Today I saw in the paper that Bengaluru Metro will extend a new route — very good news.","options":["Ivaththu paper nodide ki Bengaluru Metro navin route extend aagutte anta — thumba oLLeya samachar.","Naale paper nodide ki Bengaluru Metro navin route extend aagutte anta — thumba oLLeya samachar.","Ivaththu paper nodide ki Bengaluru Bus navin route extend aagutte anta — thumba oLLeya samachar.","Ivaththu paper keLide ki Bengaluru Metro navin route extend aagutte anta — thumba oLLeya samachar."],"correctAnswer":"Ivaththu paper nodide ki Bengaluru Metro navin route extend aagutte anta — thumba oLLeya samachar."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Rajyakarana vishaya alli naakke thumba ___ ide — ivaththu election results noduttiddeeni.","options":["asakti","novu","khushi","stress"],"correctAnswer":"asakti"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I heard the news that RCB went to this IPL final — there is a lot of excitement in Bengaluru!","wordBankItems":["RCB","ee","IPL","final","ge","hogide","anta","samachar","keLide","—","Bengaluru","alli","thumba","excitement","ide","!"],"correctAnswer":"RCB ee IPL final ge hogide anta samachar keLide — Bengaluru alli thumba excitement ide !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"varthe means?","options":["news item (formal)","newspaper","news channel","story"],"correctAnswer":"news item (formal)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006b',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe travel experiences in Kannada","Use past tense for trips — hode, nodide, tinNde","Share travel highlights and impressions"],"explanation":{"intro":"Travel experience vocabulary covers how to recount a completed trip — where you went, what you saw, what you ate, what impressed you.","culturalNote":"Travel culture in Karnataka: Karnataka is one of India''s most diverse travel destinations. Tourism zones: (1) Heritage: Hampi (UNESCO World Heritage — Vijayanagara ruins), Badami (rock-cut cave temples), Pattadakal (UNESCO — Chalukya temples), Belur-Halebid (Hoysala temples — intricate stone carving). (2) Nature: Coorg/Kodagu (coffee estates, Brahmagiri, Abbey Falls), Dandeli (wildlife + river rafting), BRT Wildlife Sanctuary, Kabini/Nagarhole (elephant safari, tiger reserve). (3) Coast: Gokarna (beach + Om beach + Mahabaleshwara temple), Udupi (Shri Krishna Matha temple + famous Udupi cuisine), Mangaluru/Mangalore (port city, Kudla — local name). (4) Mysuru (Mysore Palace, Chamundi Hills, Brindavan Gardens, silk). (5) Spiritual: Dharmasthala (Jain pilgrimage site), Sringeri (Adi Shankaracharya matha), Udupi Krishna temple, Melukote. Travel habits: Kannadigas are enthusiastic travelers within the state. Inter-state travel: Goa (beach), Kerala (backwaters), Tamil Nadu (temples) are popular destinations."},"examples":[{"sentence":"Pichle tiNgaLu naanu Coorg ge hode — coffee estate nodide, Abbey Falls alli swimming maadide, thumba enjoy maadide.","english":"Last month I went to Coorg — I saw the coffee estate, swam at Abbey Falls, I enjoyed a lot."},{"sentence":"Hampi thumba adbhuta jagath — Vijayanagara samraajya''da chihnegaLu nodidaaga naakke goosebumps aayitu.","english":"Hampi is a truly wonderful place — when I saw the signs of the Vijayanagara empire I got goosebumps."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe travel experiences and share highlights of a trip in Kannada."}}',
'{"items":[{"word":"pichle tiNgaLu","translation":"last month","transliteration":"pichle tiNgaLu","pronunciation":"PICH-le tiN-GA-Lu","example":"pichle tiNgaLu hode"},{"word":"chihnegaLu","translation":"signs/traces/remnants (of history)","transliteration":"chihnegaLu","pronunciation":"CHIH-ne-ga-Lu","example":"samraajya chihnegaLu"},{"word":"goosebumps","translation":"goosebumps (English — universally used)","transliteration":"goosebumps","pronunciation":"GOOS-bumps","example":"goosebumps aayitu"},{"word":"safari","translation":"safari (wildlife trip)","transliteration":"safari","pronunciation":"sa-FA-ri","example":"elephant safari"},{"word":"rafting","translation":"rafting (river adventure)","transliteration":"rafting","pronunciation":"RAF-ting","example":"Dandeli rafting"},{"word":"heritage","translation":"heritage (historical/cultural legacy)","transliteration":"heritage","pronunciation":"HER-i-tij","example":"UNESCO heritage site"}]}',
'{"title":"Travel experiences in Kannada — past tense recounting","pattern":"X ge hode = I went to X. X nodide = I saw X. X tinNde = I ate X. X maadide = I did X. Highlight: X ide nodidaaga/tinidaaga = when I saw/ate X (subordinate moment clause). Impression: X thumba adbhuta = X is truly wonderful. Recommend: X ge hogu — thumba channa = go to X — very beautiful (recommendation).","explanation":"Travel recounting vocabulary: past tense travel verbs — hode (went), nodide (saw), tinNde (ate), kudide (drank), maadide (did), keLide (heard), aaDide (played). Sequence: prathama...nantara...kaDeyalli (first...then...finally) for trip narrative. Impression words: adbhuta (wonderful), channagi (nicely), goosebumps aayitu (got goosebumps), manassu tumbitu (heart filled up — emotional experience). Food mention: X restaurant alli Y tinNde (I ate Y at X restaurant). People met: ooru jana tumbaa naDedu konDiddaare (the town people were very well-behaved). Recommendation: definitely X ge hogi — worth it! (definitely go to X — worth it!). Time: 2 dina/3 dina trip itu (it was a 2/3 day trip).","examples":[{"sentence":"Kabini alli elephant safari maadide — suryaastamana nodidaaga nadiige alli elephants kuDiyuttiddaaga thumba adbhuta aagiutte.","english":"I did an elephant safari at Kabini — when I saw elephants drinking in the river at sunset it was truly wonderful."},{"sentence":"Udupi ge hogidaaga Krishna Matha darshana maadide haagu Udupi cuisine tinNde — idli-sambar haagu masala dosa thumba channa.","english":"When I went to Udupi I took darshana at Krishna Matha and ate Udupi cuisine — idli-sambar and masala dosa were very good."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"chihnegaLu means?","options":["signs/traces/remnants (of history)","symbols","flags","buildings"],"correctAnswer":"signs/traces/remnants (of history)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Last month I went to Coorg — I saw the coffee estate, swam at Abbey Falls, I enjoyed a lot.","options":["Pichle tiNgaLu naanu Coorg ge hode — coffee estate nodide, Abbey Falls alli swimming maadide, thumba enjoy maadide.","Ee tiNgaLu naanu Coorg ge hode — coffee estate nodide, Abbey Falls alli swimming maadide, thumba enjoy maadide.","Pichle tiNgaLu naanu Chikmagalur ge hode — coffee estate nodide, Abbey Falls alli swimming maadide, thumba enjoy maadide.","Pichle tiNgaLu naanu Coorg ge hode — coffee estate nodide, Kabini alli swimming maadide, thumba enjoy maadide."],"correctAnswer":"Pichle tiNgaLu naanu Coorg ge hode — coffee estate nodide, Abbey Falls alli swimming maadide, thumba enjoy maadide."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Hampi thumba adbhuta jagath — Vijayanagara samraajya da chihnegaLu nodidaaga naakke ___ aayitu.","options":["goosebumps","novu","santosha","khushi"],"correctAnswer":"goosebumps"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I did an elephant safari at Kabini — when I saw elephants drinking in the river at sunset it was truly wonderful.","wordBankItems":["Kabini","alli","elephant","safari","maadide","—","suryaastamana","nodidaaga","nadiige","alli","elephants","kuDiyuttiddaaga","thumba","adbhuta","aagiutte","."],"correctAnswer":"Kabini alli elephant safari maadide — suryaastamana nodidaaga nadiige alli elephants kuDiyuttiddaaga thumba adbhuta aagiutte ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"manassu tumbitu means?","options":["heart filled up (emotional experience)","I am full (food)","I am happy","I am satisfied"],"correctAnswer":"heart filled up (emotional experience)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006c',1,'APPROVED','PUBLISHED',
'{"objectives":["Express strong opinions in Kannada","Use naanna dRiDha abipraaya vocabulary for conviction","Argue for and against a position politely"],"explanation":{"intro":"Strong opinions vocabulary covers how to express a firm view with conviction and back it up with reasons — moving beyond soft preferences to principled positions.","culturalNote":"Opinion culture in Karnataka: Kannadigas have strong opinions on several topics. (1) Kannada language pride: opinions about the importance of Kannada are deeply held — ''Kannada naamma taai naaDina bhaashe'' (Kannada is our motherland''s language). (2) Cricket: opinions about team selections, match strategy — very passionate! (3) Film: Sandalwood fans have strong opinions about actors, directors, movies. (4) Food: ''namma ooru saaru world best saaru'' (our village saaru is the world''s best saaru) — food opinions are strong. (5) Political: opinions about parties (BJP, Congress, JD(S) — the main Karnataka parties) are strongly held. (6) Regional identity: people from Dakshina Kannada, Uttara Karnataka, Old Mysore region — each area has strong regional pride alongside Karnataka pride. (7) Environmental: opinions about Western Ghats protection vs mining/development are very strongly held among educated Kannadigas."},"examples":[{"sentence":"Naanna dRiDha abipraaya enna anta andare Kannada bhaashege classical status sigabekidu — idu mukyavaadadu.","english":"My firm opinion is that the Kannada language should receive classical status — this is important."},{"sentence":"Naanu clearly heLuttini — ee policy yaariguu oLLeyagilla, change maaDabeku.","english":"I say clearly — this policy is not good for anyone, it needs to be changed."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can express strong, principled opinions and argue for a position in Kannada."}}',
'{"items":[{"word":"dRiDha abipraaya","translation":"firm opinion/strong conviction","transliteration":"dRiDha abipraaya","pronunciation":"DRI-Dha a-bi-PRAA-ya","example":"naanna dRiDha abipraaya"},{"word":"clearly","translation":"clearly (English — commonly used)","transliteration":"clearly","pronunciation":"KLEER-li","example":"clearly heLuttini"},{"word":"yaakenendare","translation":"because / the reason is that","transliteration":"yaakenendare","pronunciation":"YAA-ke-nen-DA-re","example":"yaakenendare..."},{"word":"mukya","translation":"important/key","transliteration":"mukya","pronunciation":"MUK-ya","example":"mukya vishaya"},{"word":"poorthi sahmat","translation":"completely agree","transliteration":"poorthi sahmat","pronunciation":"POOR-thi SAH-mat","example":"poorthi sahmat"},{"word":"change maaDabeku","translation":"must be changed (strong call for change)","transliteration":"change maaDabeku","pronunciation":"cheynj MAA-da-be-ku","example":"ee policy change maaDabeku"}]}',
'{"title":"Strong opinion vocabulary in Kannada — dRiDha abipraaya","pattern":"Naanna dRiDha abipraaya enna anta andare X = My firm opinion is that X. Naanu clearly heLuttini X = I say clearly X. Yaakenendare... = because... (giving reason). X mukya yaakenendare Y = X is important because Y. Strong disagreement: ee X yaariguu oLLeyagilla (this X is not good for anyone). Call for change: X change maaDabeku (X must be changed).","explanation":"Strong opinion expressions in Kannada: (1) Conviction: naanna dRiDha abipraaya (my firm opinion), naanu poorthi nambuttini (I completely believe). (2) Reasoning: yaakenendare (because), idu mukya yaakenendare (this is important because). (3) Emphasis: clearly, definitely (English — both used), nishchayavaagi (certainly). (4) Calling for action: X maaDabeku (X must be done), X change aagabeku (X must change), X aagabekku (X should happen). (5) Asserting truth: idu nijavaada vishaya (this is a true/real matter), statistics ide (there is data/statistics). (6) Refuting: idu sarigalla yaakenendare (this is wrong because). Tone: strong opinions can be expressed passionately but without personal attacks — focus on the issue, not the person.","examples":[{"sentence":"Naanna abipraayalli Western Ghats conservation thumba mukya — yaakenendare adu Karnataka''a jala saulabha source.","english":"In my opinion Western Ghats conservation is very important — because it is Karnataka''s water availability source."},{"sentence":"Naanu clearly heLuttini — traffic problem Bengaluru alli definitely solve aagabekku, idu postpone aagabaardadu.","english":"I say clearly — the traffic problem in Bengaluru must definitely be solved, it should not be postponed."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"dRiDha abipraaya means?","options":["firm opinion/strong conviction","mild opinion","agreement","suggestion"],"correctAnswer":"firm opinion/strong conviction"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"My firm opinion is that the Kannada language should receive classical status — this is important.","options":["Naanna dRiDha abipraaya enna anta andare Kannada bhaashege classical status sigabekidu — idu mukyavaadadu.","Nimage dRiDha abipraaya enna anta andare Kannada bhaashege classical status sigabekidu — idu mukyavaadadu.","Naanna dRiDha abipraaya enna anta andare Hindi bhaashege classical status sigabekidu — idu mukyavaadadu.","Naanna swalpa abipraaya enna anta andare Kannada bhaashege classical status sigabekidu — idu mukyavaadadu."],"correctAnswer":"Naanna dRiDha abipraaya enna anta andare Kannada bhaashege classical status sigabekidu — idu mukyavaadadu."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanna abipraayalli Western Ghats conservation thumba mukya — ___ adu Karnataka a jala saulabha source.","options":["yaakenendare","aadare","haagu","aadaruvu"],"correctAnswer":"yaakenendare"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I say clearly — the traffic problem in Bengaluru must definitely be solved, it should not be postponed.","wordBankItems":["Naanu","clearly","heLuttini","—","traffic","problem","Bengaluru","alli","definitely","solve","aagabekku",",","idu","postpone","aagabaardadu","."],"correctAnswer":"Naanu clearly heLuttini — traffic problem Bengaluru alli definitely solve aagabekku , idu postpone aagabaardadu ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"yaakenendare means?","options":["because / the reason is that","therefore","although","if"],"correctAnswer":"because / the reason is that"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006d',1,'APPROVED','PUBLISHED',
'{"objectives":["Conduct shopping and bargaining conversations in Kannada","Use ella kaDime maaDi, naramssu heeLi for bargaining","Ask for discounts and negotiate price politely"],"explanation":{"intro":"Shopping and bargaining vocabulary covers the full conversation flow in a market — asking prices, bargaining, getting discounts, and completing a purchase.","culturalNote":"Shopping culture in Karnataka: (1) Markets: Devaraja Market in Mysuru — vegetables, flowers (marigold, jasmine), spices. Krishna Rajendra Market (KR Market) in Bengaluru — wholesale flowers and vegetables. Commercial Street, Chickpet, Jayanagar 4th Block — famous Bengaluru shopping areas. (2) Bargaining: expected and normal in street markets and smaller shops. Fixed-price shops (malls, brand stores) — no bargaining. ''Last price enu?'' (what is the final/last price?) is the classic bargain opener. (3) Silk shopping: Mysuru silk (Mysore Silk) is world-famous — government silk factory store has fixed prices, but private dealers negotiate. (4) Flower market: Bengaluru''s wholesale flower market at 3-4am is famous — mogra (jasmine), marigold (chendu hoovvu). (5) Vegetable market: weekly shanty (weekly market) in smaller towns — price negotiation is normal. (6) Online shopping: Flipkart (Bengaluru-based!) and Amazon are widely used. (7) Textile: Ilkal saree (Ilkal, Bagalkot district) — famous Karnataka handloom; Channapatna toys — famous lacquered wood toys from Channapatna town."},"examples":[{"sentence":"Ee sari beladhalli ella kaDime maaDi — eshtu last price?","english":"Please reduce the price of this sari a little — what is the final price?"},{"sentence":"Naanu 500 koDuttini, eshtu? Aadare naakke 450 aadare better — deal aagutte?","english":"I will give 500, how about? But if it is 450 for me it is better — does the deal work?"}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can conduct shopping and bargaining conversations in Kannada markets."}}',
'{"items":[{"word":"kaDime maaDi","translation":"please reduce (the price) — bargaining phrase","transliteration":"kaDime maaDi","pronunciation":"ka-DI-me MAA-Di","example":"beladhalli kaDime maaDi"},{"word":"last price","translation":"final price (bargaining — what is the bottom line?)","transliteration":"last price","pronunciation":"laast PRAI-s","example":"last price enu?"},{"word":"deal","translation":"deal (agreement on price — English used)","transliteration":"deal","pronunciation":"deel","example":"deal aagutte?"},{"word":"discount","translation":"discount (English — widely used)","transliteration":"discount","pronunciation":"DIS-kawnt","example":"discount ide?"},{"word":"koDuttini","translation":"I will give (money)","transliteration":"koDuttini","pronunciation":"ko-DUT-ti-ni","example":"500 koDuttini"},{"word":"tight maaDi","translation":"pack it up (request to pack purchase)","transliteration":"tight maaDi","pronunciation":"tait MAA-Di","example":"tight maaDi koDi"}]}',
'{"title":"Bargaining vocabulary in Kannada — kaDime maaDi","pattern":"Eshtu aagutte? = how much does it cost? Ella kaDime maaDi = please reduce a little. Last price enu? = what is the final price? Naanu X koDuttini = I will give X (rupees). X aadare deal aagutte? = if it is X, does the deal work? Too expensive: thumba jaasthi ide / ee beladhalli siguttilla (too expensive / won''t get it at this price — implying walking away).","explanation":"Bargaining conversation flow in Kannada: (1) Opening: X ge eshtu? (how much for X?). (2) Reaction: thumba jaasthi aagutte (too expensive), swalpa kaDime maaDi (please reduce a little). (3) Counteroffer: naanu X koDuttini (I will give X). (4) Seller response: X anta kaDime maaDagalla (can''t reduce below X) OR sari, X koDi (okay, give X). (5) Close: deal aayitu (deal is done), tight maaDi koDi (pack it up and give). (6) Payment: exact change ide (I have exact change), card aagutte? (does card work?). Context: use this in outdoor markets (angaDi), weekly markets (shanty), small textile stores, souvenir shops. Do NOT bargain in malls, government stores, or branded shops — fixed price (fixed price / MRP).","examples":[{"sentence":"Dukaan waala heLidaare 1200 anta — naanu 800 heLide, avanu 1000 anda, naanu 900 koDuttini anta heLide — deal aayitu!","english":"The shopkeeper said 1200 — I said 800, he said 1000, I said I will give 900 — the deal was done!"},{"sentence":"Mysuru Market alli Ilkal sari nodide — thumba channa itu aadare beladhu jaasthi itu — bargain maaDide, kaDime aayitu.","english":"I saw an Ilkal sari in Mysuru Market — it was very beautiful but the price was high — I bargained, it was reduced."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"kaDime maaDi means?","options":["please reduce (the price)","please increase","please pack","please show"],"correctAnswer":"please reduce (the price)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Please reduce the price of this sari a little — what is the final price?","options":["Ee sari beladhalli ella kaDime maaDi — eshtu last price?","Ee sari beladhalli jaasthi maaDi — eshtu last price?","Ee churidar beladhalli ella kaDime maaDi — eshtu last price?","Ee sari beladhalli ella kaDime maaDi — enu last price?"],"correctAnswer":"Ee sari beladhalli ella kaDime maaDi — eshtu last price?"},{"id":"ex3","type":"FILL_IN_BLANK","question":"Naanu 500 koDuttini, eshtu? Aadare naakke 450 aadare better — ___ aagutte?","options":["deal","price","bargain","discount"],"correctAnswer":"deal"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The shopkeeper said 1200 — I said 800, he said 1000, I said I will give 900 — the deal was done!","wordBankItems":["Dukaan","waala","heLidaare","1200","anta","—","naanu","800","heLide",",","avanu","1000","anda",",","naanu","900","koDuttini","anta","heLide","—","deal","aayitu","!"],"correctAnswer":"Dukaan waala heLidaare 1200 anta — naanu 800 heLide , avanu 1000 anda , naanu 900 koDuttini anta heLide — deal aayitu !"},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"tight maaDi means?","options":["pack it up (request to pack purchase)","reduce price","show me","wrap loosely"],"correctAnswer":"pack it up (request to pack purchase)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('11000000-0000-0000-0000-00000000006e',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe problems and seek solutions in Kannada","Use problem, samasye, and solution vocabulary","Ask for help and propose solutions"],"explanation":{"intro":"Problem-solving vocabulary covers how to describe a problem clearly, ask for help, propose a solution, and respond to problems — from everyday glitches to workplace challenges.","culturalNote":"Problem-solving culture in Karnataka: the Bengaluru IT culture has normalized structured problem-solving. Terms like ''root cause'' (root cause analysis — RCA), ''fix'' (fix this bug), ''workaround'' (temporary fix) are used mixing Kannada and English. Civic problems: BBMP (Bruhat Bengaluru Mahanagara Palike — Bengaluru municipal corporation) is famous for pothole complaints. ''Bengaluru pothole'' is practically a meme. Complaint culture: filing a complaint (complaint maaDuvudu) is increasingly common — BBMP Sahaaya helpline, traffic police complaint portal. Family problems: family disputes are usually mediated by respected elders — panchayat style resolution (elder''s council judgment). Agricultural problems: water scarcity (neeru samasye), crop failure (beleya naashu) are serious rural problems. Solution-seeking: ''yaav solution ide?'' (what solution is there?) is a common phrasing. Jugaad: the Indian concept of resourceful improvised solutions — Kannada equivalent: ''hege aadaruu maaDovudu'' (somehow managing to do it)."},"examples":[{"sentence":"Namma office alli thumba heechaada samasye ide — naanu manager ge heLide, avaru solution heLuttaare anta nambuttiddeeni.","english":"There is a very big problem in our office — I told the manager, I am trusting that they will tell a solution."},{"sentence":"Internet kaeLide — technician ge call maaDide, avaru 2 gante alli fix maaDuttaare anta heLidaare.","english":"The internet went down — I called the technician, they said they will fix it in 2 hours."}],"rewards":{"xp":100,"coins":50},"metadata":{"estimatedMinutes":15,"canDo":"I can describe problems and seek solutions in Kannada."}}',
'{"items":[{"word":"samasye","translation":"problem/issue/difficulty","transliteration":"samasye","pronunciation":"sa-MAS-ye","example":"thumba heechaada samasye"},{"word":"solution","translation":"solution (English — widely used)","transliteration":"solution","pronunciation":"sa-LOO-shen","example":"yaav solution ide?"},{"word":"fix maaDuvudu","translation":"to fix/repair (IT and general)","transliteration":"fix maaDuvudu","pronunciation":"fiks MAA-du-vu-du","example":"issue fix maaDide"},{"word":"report maaDuvudu","translation":"to report (a complaint or issue)","transliteration":"report maaDuvudu","pronunciation":"ri-PORT MAA-du-vu-du","example":"problem report maadide"},{"word":"temporary","translation":"temporary (short-term solution — workaround)","transliteration":"temporary","pronunciation":"TEM-po-rer-i","example":"temporary fix"},{"word":"permanently","translation":"permanently (long-term solution)","transliteration":"permanently","pronunciation":"PUR-ma-nent-li","example":"permanently solve maaDabeku"}]}',
'{"title":"Samasye haagu solution — problem and solution vocabulary in Kannada","pattern":"X samasye ide = there is a problem with X. Yaav solution ide? = what solution is there? X heLide — avaru Y heLidaare = I told X — they said Y (reporting the chain). Reporting a problem: manager/technician/BBMP ge heLide (I told the manager/technician/BBMP). Fixing: fix maaDuttaare (they will fix), solve aagutte (it will be solved), aagutte (it will work out — optimistic).","explanation":"Problem vocabulary in Kannada: samasye (problem — also samasyeyu), kashta (difficulty/hardship), trouble (trouble — English), issue (issue — English), problem (problem — English). Solution vocabulary: solution (solution — English), parikara (remedy/solution — formal Kannada), fix (fix — IT), repair (repair), resolve maaDuvudu (to resolve). Problem escalation: manager ge heLuvudu (tell the manager), complaint maaDuvudu (file complaint), help keLuvudu (ask for help). Temporary vs permanent: temporary fix (stopgap solution), permanently solve maaDuvudu (solve permanently). Resolution confirmation: aayitu / sari aayitu (done / it is fixed). Checking: X sari aayitaa? (is X fixed?). Common problem phrases: network problem (network issue), light hogide (power cut), door opening aguttilla (door won''t open), tap kaeLide (tap isn''t working).","examples":[{"sentence":"Namma apartment alli neeru samasye ide — BWSSB ge report maadide aadare inna fix aagilla.","english":"There is a water problem in our apartment — I reported to BWSSB but it is still not fixed."},{"sentence":"Ee bug root cause enu anta nambuttilla — temporarily fix maadide, aadare permanently solve maaDabeku.","english":"I don''t know the root cause of this bug — I temporarily fixed it, but it needs to be solved permanently."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"samasye means?","options":["problem/issue/difficulty","solution","complaint","request"],"correctAnswer":"problem/issue/difficulty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"There is a very big problem in our office — I told the manager, I am trusting that they will tell a solution.","options":["Namma office alli thumba heechaada samasye ide — naanu manager ge heLide, avaru solution heLuttaare anta nambuttiddeeni.","Namma office alli swalpa samasye ide — naanu manager ge heLide, avaru solution heLuttaare anta nambuttiddeeni.","Nimma office alli thumba heechaada samasye ide — naanu manager ge heLide, avaru solution heLuttaare anta nambuttiddeeni.","Namma office alli thumba heechaada samasye ide — naanu HR ge heLide, avaru solution heLuttaare anta nambuttiddeeni."],"correctAnswer":"Namma office alli thumba heechaada samasye ide — naanu manager ge heLide, avaru solution heLuttaare anta nambuttiddeeni."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ee bug root cause enu anta nambuttilla — temporarily fix maadide, aadare ___ solve maaDabeku.","options":["permanently","temporarily","quickly","slowly"],"correctAnswer":"permanently"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: There is a water problem in our apartment — I reported to BWSSB but it is still not fixed.","wordBankItems":["Namma","apartment","alli","neeru","samasye","ide","—","BWSSB","ge","report","maadide","aadare","inna","fix","aagilla","."],"correctAnswer":"Namma apartment alli neeru samasye ide — BWSSB ge report maadide aadare inna fix aagilla ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"aagutte (in problem context) means?","options":["it will work out (optimistic)","it is broken","there is a problem","it happened"],"correctAnswer":"it will work out (optimistic)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

